#: 後で変わるかもしれない部品のコードは import しない。
FORMER_TAX_MODES = {
    "line_round": ("各行四捨五入", "round", "四捨五入"),
    "line_floor": ("各行切捨", "floor", "切捨"),
}


def move_to_total(apps, schema_editor):
    """明細ごとの扱いの会社の行を、トータルと前の向きに移す。移した行ごとに記録の 1 行を出す。移す行が無ければ何も出さない。"""
    Company = apps.get_model("core", "Company")
    logger = logging.getLogger("seizou.settings")
    for company in Company.objects.filter(tax_mode__in=list(FORMER_TAX_MODES)).order_by("pk"):
        former, rounding, rounding_label = FORMER_TAX_MODES[company.tax_mode]
        company.tax_mode = "total"
        company.tax_rounding = rounding
        company.save(update_fields=["tax_mode", "tax_rounding"])
        message = (
            f"会社の消費税の扱いを {former} からトータルに移し、消費税の端数の向きを {rounding_label} にした"
            f" (インボイス制度。core の migration): {company.name}"
        )
        logger.info(message)
        print(message)


